sys_script_include.script:
var BaseRegistrationGuard = Class.create();
BaseRegistrationGuard.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    isBaseFull: function() {
        var baseId    = this.getParameter('sysparm_base_id')    || '';
        var excludeId = this.getParameter('sysparm_exclude_id') || '';
        var out = { ok: true, count: 0, capacity: 0 };

        if (!baseId) return JSON.stringify({ ok: false, reason: 'MISSING_BASE' });

        var baseGR = new GlideRecord('x_1834930_office_0_office_base');
        if (!baseGR.get(baseId)) return JSON.stringify({ ok: false, reason: 'INVALID_BASE' });

        var cap = parseInt(baseGR.getValue('max_capacity'), 10) || 0;
        out.capacity = cap;

        if (cap > 0) {
            var reg = new GlideRecord('x_1834930_office_0_base_registration');
            reg.addQuery('base', baseId);
            reg.addQuery('state', 'IN', '1,2');
            if (excludeId) reg.addQuery('sys_id', '!=', excludeId);
            reg.query();
            var cnt = 0; while (reg.next()) cnt++;
            out.count = cnt;

            if (cnt >= cap) out.ok = false;
        }
        return JSON.stringify(out);
    },

    hasUserActiveRegistration: function() {
        var userId    = this.getParameter('sysparm_user_id')    || '';
        var excludeId = this.getParameter('sysparm_exclude_id') || '';
        if (!userId) return JSON.stringify({ ok: true });

        var dup = new GlideRecord('x_1834930_office_0_base_registration');
        dup.addQuery('user', userId);
        dup.addQuery('state', 'IN', '1,2');
        if (excludeId) dup.addQuery('sys_id', '!=', excludeId);
        dup.setLimit(1);
        dup.query();

        if (dup.next()) {
            return JSON.stringify({
                ok: false,
                registration: dup.getUniqueValue(),
                base: dup.getValue('base'),
                state: dup.getValue('state')
            });
        }
        return JSON.stringify({ ok: true });
    },

    type: 'BaseRegistrationGuard'
});
